<?php
// Run with the multipart fixtures generated by run-sqlite.sh.
chdir(getenv('DISKQUOTA_TEST_ROOT'));
require 'bootstrap.php';

try {
    $app = Omeka\Mvc\Application::init(require 'application/config/application.config.php');
    $services = $app->getServiceManager();
    $db = $services->get('Omeka\Connection');
    $api = $services->get('Omeka\ApiManager');
    $admin = $services->get('Omeka\EntityManager')->getRepository(Omeka\Entity\User::class)
        ->findOneBy(['email' => 'admin@example.com']);
    $services->get('Omeka\AuthenticationService')->getStorage()->write($admin);
    $services->get('Omeka\Settings')->set('media_type_whitelist', ['text/plain', 'application/octet-stream']);
    $users = $services->get('Omeka\Settings\User');
    $users->setTargetId($admin->getId());
    $users->set('diskquota_user_quota', 0);
    $sites = $services->get('Omeka\Settings\Site');
    $files = $services->get('Request')->getFiles()->toArray();
    $base = $services->get('Config')['file_store']['local']['base_path'] ?: OMEKA_PATH . '/files';
    $failures = 0;
    $check = function ($valid, $message) use (&$failures) {
        echo ($valid ? 'PASS: ' : 'FAIL: ') . $message . "\n";
        $failures += $valid ? 0 : 1;
    };
    $snapshot = function () use ($db, $base) {
        return [$db->fetchOne('SELECT COUNT(*) FROM media'), $db->fetchOne('SELECT COUNT(*) FROM item'),
            glob($base . '/original/*')];
    };
    $reject = function ($operation, $name) use ($check, $snapshot) {
        $before = $snapshot();
        $rejected = false;
        try {
            $operation();
        } catch (Omeka\Api\Exception\ValidationException $e) {
            $errors = $e->getErrorStore()->getErrors();
            $rejected = isset($errors['file']) || isset($errors['o:media'][0]['file']);
        }
        $check($rejected, $name);
        $check($before == $snapshot(), "$name leaves no orphan records/files");
    };
    $site = $api->create('sites', [
        'o:title' => 'Pending uploads', 'o:slug' => 'pending-uploads', 'o:theme' => 'default',
    ])->getContent();
    $item = $api->create('items', ['o:site' => [['o:id' => $site->id()]]])->getContent();
    $upload = fn ($index) => ['o:ingester' => 'upload', 'file_index' => $index];
    $sites->setTargetId($site->id());
    $sites->set('diskquota_site_quota', 0);
    $seed = $api->create('media', $upload(6) + ['o:item' => ['o:id' => $item->id()]], $files)->getContent();
    $sites->setTargetId($site->id());
    $sites->set('diskquota_site_quota', 1);
    $reject(
        fn () => $api->create('media', $upload(3) + ['o:item' => ['o:id' => $item->id()]], $files),
        'selected file size ignores the smaller first multipart file'
    );
    $empty = $api->create('sites', [
        'o:title' => 'Batch uploads', 'o:slug' => 'batch-uploads', 'o:theme' => 'default',
    ])->getContent();
    $sites->setTargetId($empty->id());
    $sites->set('diskquota_site_quota', 1);
    $reject(fn () => $api->create('items', [
        'o:site' => [['o:id' => $empty->id()]], 'o:media' => [$upload(0), $upload(1)],
    ], $files), 'site quota includes pending uploads in the same item');
    $reject(fn () => $api->create('items', [
        'o:site' => [['o:id' => $empty->id()]], 'o:media' => [$upload(11), $upload(12), $upload(13)],
    ], $files), 'rejected third upload cleans both previously accepted files');
    $sites->setTargetId($empty->id());
    $sites->set('diskquota_site_quota', 0);
    $manager = $services->get('DiskQuota\DiskQuotaManager');
    $users->setTargetId($admin->getId());
    $users->set('diskquota_user_quota', (int) ceil($manager->getUsedDiskSpaceByUser($admin->getId()) / 1048576) + 3);
    $reject(fn () => $api->create('items', [
        'o:site' => [['o:id' => $empty->id()]], 'o:media' => [$upload(4), $upload(5)],
    ], $files), 'user quota includes pending uploads in the same item');
    $users->setTargetId($admin->getId());
    $users->set('diskquota_user_quota', 0);
    $em = $services->get('Omeka\EntityManager');
    $em->refresh($em->find(Omeka\Entity\Item::class, $item->id()));
    $reject(fn () => $api->update('items', $item->id(), [
        'o:media' => [['o:id' => $seed->id()], $upload(7), $upload(2)],
    ], $files, ['isPartial' => true]), 'rejected item update preserves existing originals');
    $retry = $api->create('media', $upload(9) + ['o:item' => ['o:id' => $item->id()]], $files)->getContent();
    $check((int) $retry->size() === 409600, 'rejected item update releases pending bytes for a retry');
    $sites->setTargetId($empty->id());
    $sites->set('diskquota_site_quota', 1);
    $accepted = $api->create('items', [
        'o:site' => [['o:id' => $empty->id()]], 'o:media' => [$upload(8)],
    ], $files)->getContent();
    $check((int) $accepted->media()[0]->size() === 1048576, 'exact quota remains usable after rejected operations');
    $owner = $api->create('users', [
        'o:name' => 'Other owner', 'o:email' => 'owner@example.com', 'o:role' => 'researcher', 'o:is_active' => true,
    ])->getContent();
    $users->setTargetId($owner->id());
    $users->set('diskquota_user_quota', 0);
    $users->setTargetId($admin->getId());
    $users->set('diskquota_user_quota', 1);
    $otherItem = $api->create('items', [
        'o:owner' => ['o:id' => $owner->id()], 'o:site' => [], 'o:media' => [],
    ])->getContent();
    $owned = $api->create('media', $upload(10) + ['o:item' => ['o:id' => $otherItem->id()]], $files)->getContent();
    $check($owned->owner()->id() === $owner->id(), 'quota follows media ownership when the uploader differs');
    echo 'AUDIT_RESULT=' . ($failures ? 'FAIL' : 'PASS') . "\n";
    if ($failures) {
        http_response_code(500);
    }
} catch (Throwable $e) {
    http_response_code(500);
    echo get_class($e) . ': ' . $e->getMessage() . "\nAUDIT_RESULT=FAIL\n";
    if ($e instanceof Omeka\Api\Exception\ValidationException) {
        echo json_encode($e->getErrorStore()->getErrors(), JSON_PRETTY_PRINT) . "\n";
    }
}
